        assertEquals("equals", m.getName());
    }

    @Test
    public void testLookupMethodTargetClassConversion() throws Exception {
        // targetClass is Number, parameters[0] is Integer (5)
        // TypeUtils converts Integer to Number instance (class is Integer)
        // Lookup method on Integer class
        Method m = MethodLookupUtils.lookupMethod(Number.class, "intValue", new Object[] { Integer.valueOf(5) });
        assertNotNull(m);
        // Since the actual class becomes Integer, we find Integer.intValue()
        assertEquals(int.class, m.getReturnType());
    }

    @Test
    public void testLookupMethodNullArgumentDisablesExact() throws Exception {
        // String.regionMatches(boolean, int, String, int, int)
        // If we pass null for a middle arg, exact match is disabled.
        Method m = MethodLookupUtils.lookupMethod(
            String.class, 
            "regionMatches", 
            new Object[] { "source", true, 0, null, 0, 0 }
        );
        // Even with null, it should find the method via the loop/conversion logic if compatible
        // or exact match if types[?] is null (cannot call getMethod with null type).
        // Code disables tryExact if types[i] == null.
        // So it goes to the loop.
        assertNotNull(m);
        assertEquals("regionMatches", m.getName());
    }

    @Test
    public void testLookupMethodStaticMethodIgnored() throws Exception {
        // String.valueOf(int) is static.
        // We want instance methods.
        // Params: [String, "valueOf", "text", 1]
        // "text" converted to String. lookup on String.
        // valueOf is static. Should be ignored in the loop (Modifier.isStatic check).
        // Should return null because no instance method valueOf takes (String, int).
        Method m = MethodLookupUtils.lookupMethod(String.class, "valueOf", new Object[] { "text", 1 });
        assertNull(m);
    }

    @Test
    public void testLookupMethodPrimitiveParameterConversion() throws Exception {
        // ArrayList.ensureCapacity(int)
        // Params: [ArrayList, "ensureCapacity", new ArrayList(), Integer(10)]
        // param 0: ArrayList. targetClass ArrayList. OK.
        // args: [Integer(10)].
        // Method param: int.
        // matchParameterTypes handles primitive widening (Integer -> int).
        Method m = MethodLookupUtils.lookupMethod(
            ArrayList.class, 
            "ensureCapacity", 
            new Object[] { new ArrayList(), Integer.valueOf(10) }
        );
        assertNotNull(m);
        assertEquals("ensureCapacity", m.getName());
        assertEquals(int.class, m.getParameterTypes()[0]);
    }

    @Test
    public void testLookupMethodSpecificOverloadSelection() throws Exception {
        // String.getBytes(String charsetName)
        // vs String.getBytes()
        // Params: [String, "getBytes", "text", "UTF-8"]
        // Arg 0: "UTF-8" (String).
        // Should select getBytes(String).
        Method m = MethodLookupUtils.lookupMethod(
            String.class, 
            "getBytes", 
            new Object[] { "text", "UTF-8" }
        );
        assertNotNull(m);
        assertEquals("getBytes", m.getName());
        assertEquals(1, m.getParameterTypes().length);
        assertEquals(String.class, m.getParameterTypes()[0]);
    }
